entById('rule-edit-btn'),saveBtn=document.getElementById('rule-save-btn'),cancelBtn=document.getElementById('rule-cancel-btn'),allInputs=m.querySelectorAll('input:not([type=hidden]),select');function setEdit(v){allInputs.forEach(function(i){i.disabled=!v;});editBtn.style.display=v?'none':'';saveBtn.style.display=v?'':'none';cancelBtn.style.display=v?'':'none';}function openRule(a){try{var raw=JSON.parse(a.getAttribute('data-rule-raw'));}catch(e){return;}document.getElementById('rule-modal-title').textContent=(raw.name||'')+' #'+(raw.id||'')+(raw.created_at?' \xb7 '+raw.created_at.substring(0,10):'');document.getElementById('rule-edit-id').value=raw.id||'';document.getElementById('re-type').value=raw.rule_type||'percent';document.getElementById('re-value').value=raw.value||0;document.getElementById('re-property-text').textContent=raw.property_name||raw.property||'';document.getElementById('re-status').value=raw.status||'active';document.getElementById('re-priority').value=raw.priority||100;document.getElementById('re-stackable').checked=!!raw.stackable;document.getElementById('re-promo').value=raw.promo_code||'';document.getElementById('re-bstart').value=raw.booking_start||'';document.getElementById('re-bend').value=raw.booking_end||'';document.getElementById('re-sstart').value=raw.stay_start||'';document.getElementById('re-send').value=raw.stay_end||'';document.getElementById('re-minadv').value=raw.min_advance_days||0;document.getElementById('re-markets').value=raw.markets||'';document.getElementById('re-nats').value=raw.nationalities||'';document.getElementById('re-chans').value=raw.channels||'';document.getElementById('re-adults').value=raw.adults||0;document.getElementById('re-children').value=raw.children||0;var rateSel=document.getElementById('re-rate');if(raw.rate_plan_id)rateSel.value=raw.rate_plan_id;setEdit(false);m.hidden=false;document.body.style.overflow='hidden';}function closeRule(){m.hidden=true;document.body.style.overflow='';setEdit(false);}editBtn.addEventListener('click',function(){setEdit(true);});cancelBtn.addEventListener('click',function(){closeRule();});document.addEventListener('click',function(e){var t=e.target;if(t&&t.classList&&t.classList.contains('rule-detail-link')){e.preventDefault();openRule(t);return;}if(t===m||t.classList.contains('rule-modal-backdrop')||t.id==='rule-modal-close')closeRule();});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&!m.hidden)closeRule();});})();</script><?php supply_end();
